  if (selectedTemplate) {
    beefreeSDKInstance.start(selectedTemplate);
    console.log('Loaded template from localStorage');
  } else {
    // Start with empty template
              beefreeSDKInstance.start();
          console.log('Started with empty template');
  }
  ```

